INSERT INTO travel_profiles (code, nickname, description, image_key, created_at, updated_at) VALUES
('HPSRI', '프라이빗 무드 컬렉터', '유명한 곳일수록 특별하게, 아낌없이 누리는 나만의 시간을 사랑하는 여행자예요. 핫플레이스의 분위기를 눈과 마음에 느긋하게 담아내며, 혼자만의 여백 있는 일정에서 가장 큰 만족을 느껴요.', NULL, NOW(), NOW()),
('HPSRG', '럭셔리 무드 메이트', '소중한 사람들과 함께 프리미엄한 공간에서 여유를 즐기는 여행자예요. 유명 명소의 분위기를 감상하며 느긋하게 흘러가는 일정 속에서, 함께하는 시간 자체가 여행의 목적이 돼요.', NULL, NOW(), NOW()),
('HPSAI', '시티 뷰 헌터', '도시의 핫플레이스를 부지런히 돌며 멋진 장면을 수집하는 혼행 여행자예요. 비용보다 경험의 밀도를 중시하고, 하루를 꽉 채운 일정 속에서 인생 뷰와 감성 스팟을 눈에 담아요.', NULL, NOW(), NOW()),
('HPSAG', '핫플 투어 캡틴', '일행을 이끌고 유명 명소를 알차게 도는 에너지 넘치는 여행자예요. 좋은 것은 아끼지 않고 함께 누리며, 부지런한 동선으로 도시의 볼거리를 빠짐없이 감상해요.', NULL, NOW(), NOW()),
('HPERI', '프리미엄 체험 수집가', '유명한 곳에서 직접 해보는 특별한 경험에 기꺼이 투자하는 혼행 여행자예요. 느긋한 페이스로 하나하나 깊이 있게 체험하며, 나만의 속도로 여행을 완성해요.', NULL, NOW(), NOW()),
('HPERG', '럭셔리 체험 메이트', '소중한 사람들과 핫플레이스의 특별한 체험을 함께 나누는 여행자예요. 비용보다 추억의 깊이를 중시하고, 여유로운 일정 속에서 함께 만드는 경험을 소중히 여겨요.', NULL, NOW(), NOW()),
('HPEAI', '풀코스 액티비티 헌터', '도시의 핫한 체험을 하루 가득 담아내는 열정적인 혼행 여행자예요. 특별한 경험에는 아낌없이 투자하고, 부지런히 움직이며 직접 몸으로 부딪히는 여행을 즐겨요.', NULL, NOW(), NOW()),
('HPEAG', '프리미엄 원정대장', '일행과 함께 유명한 체험을 정복하듯 즐기는 액티브한 여행자예요. 좋은 경험엔 과감히 지갑을 열고, 빈틈없는 일정으로 모두의 버킷리스트를 채워줘요.', NULL, NOW(), NOW()),
('HVSRI', '실속 감성 산책자', '합리적인 소비로 핫플레이스의 감성을 여유롭게 누리는 혼행 여행자예요. 유명한 곳도 나만의 느긋한 속도로 감상하며, 가성비 좋은 스팟에서 알찬 만족을 찾아내요.', NULL, NOW(), NOW()),
('HVSRG', '가성비 무드 메이트', '함께하는 사람들과 부담 없이 유명 명소의 분위기를 즐기는 여행자예요. 알뜰한 소비로도 감성은 놓치지 않고, 여유로운 일정 속에서 함께 웃는 시간을 만들어요.', NULL, NOW(), NOW()),
('HVSAI', '알뜰 시티 헌터', '가성비 루트로 도시의 볼거리를 부지런히 섭렵하는 혼행 여행자예요. 적은 비용으로도 인생 샷과 명소 감상을 알차게 챙기며, 꽉 찬 하루에서 성취감을 느껴요.', NULL, NOW(), NOW()),
('HVSAG', '실속 투어 리더', '일행과 함께 알뜰하고 알차게 유명 명소를 도는 여행자예요. 합리적인 동선과 소비로 볼거리를 최대한 챙기며, 함께 부지런히 움직이는 여행에서 즐거움을 찾아요.', NULL, NOW(), NOW()),
('HVERI', '가성비 체험 러버', '합리적인 가격의 체험을 골라 느긋하게 즐기는 혼행 여행자예요. 유명한 곳의 인기 체험도 실속 있게 접근하고, 서두르지 않는 일정 속에서 직접 해보는 재미를 만끽해요.', NULL, NOW(), NOW()),
('HVERG', '실속 체험 메이트', '함께하는 사람들과 부담 없는 체험을 나누며 여유를 즐기는 여행자예요. 가성비 좋은 액티비티를 찾아내는 안목이 있고, 느긋한 페이스로 함께 만드는 추억을 아껴요.', NULL, NOW(), NOW()),
('HVEAI', '에너지 실속 탐험가', '알뜰한 소비로 도시의 체험을 하루 가득 채우는 혼행 여행자예요. 부지런히 움직이며 직접 해보는 것을 좋아하고, 적은 비용으로 최대의 경험을 뽑아내는 데 능해요.', NULL, NOW(), NOW()),
('HVEAG', '가성비 원정대장', '일행을 이끌고 실속 있는 체험 코스를 정복하는 액티브한 여행자예요. 합리적인 소비로 모두가 만족할 체험을 찾아내고, 빈틈없는 일정으로 하루를 알차게 채워요.', NULL, NOW(), NOW()),
('LPSRI', '골목 무드 감별사', '잘 알려지지 않은 로컬의 분위기를 아낌없이 누리는 혼행 여행자예요. 골목 상권의 숨은 공간을 느긋하게 감상하며, 프리미엄한 취향으로 나만의 장소를 발굴해요.', NULL, NOW(), NOW()),
('LPSRG', '로컬 무드 메이트', '소중한 사람들과 골목의 감성을 여유롭게 나누는 여행자예요. 로컬의 좋은 공간에는 기꺼이 투자하고, 느긋한 일정 속에서 함께 분위기에 스며드는 시간을 사랑해요.', NULL, NOW(), NOW()),
('LPSAI', '골목 감성 헌터', '로컬 구석구석을 부지런히 누비며 숨은 감성 스팟을 찾아내는 혼행 여행자예요. 좋은 발견에는 아낌없이 투자하고, 꽉 찬 일정으로 동네의 매력을 눈에 담아요.', NULL, NOW(), NOW()),
('LPSAG', '로컬 투어 캡틴', '일행을 이끌고 로컬의 숨은 명소를 알차게 도는 여행자예요. 좋은 것은 함께 누려야 한다는 주의로, 부지런한 동선 속에 골목의 볼거리를 가득 담아요.', NULL, NOW(), NOW()),
('LPERI', '로컬 체험 소믈리에', '로컬만의 특별한 체험을 골라 깊이 있게 음미하는 혼행 여행자예요. 좋은 경험에는 비용을 아끼지 않고, 느긋한 페이스로 동네의 삶을 직접 겪어보는 것을 즐겨요.', NULL, NOW(), NOW()),
('LPERG', '프리미엄 로컬 메이트', '함께하는 사람들과 로컬의 특별한 체험에 기꺼이 투자하는 여행자예요. 여유로운 일정 속에서 골목의 공방, 클래스, 로컬 문화를 함께 몸소 경험하며 추억을 쌓아요.', NULL, NOW(), NOW()),
('LPEAI', '골목 모험 헌터', '로컬의 체험거리를 하루 가득 정복하는 열정적인 혼행 여행자예요. 특별한 경험엔 아낌없이 투자하고, 부지런히 골목을 누비며 직접 부딪히는 모험을 즐겨요.', NULL, NOW(), NOW()),
('LPEAG', '로컬 원정대장', '일행과 함께 로컬의 이색 체험을 섭렵하는 액티브한 여행자예요. 좋은 경험에 과감히 투자하고, 알찬 일정으로 모두에게 동네의 진짜 매력을 안내해요.', NULL, NOW(), NOW()),
('LVSRI', '동네 감성 산책자', '알뜰한 여행으로 골목의 정취를 느긋하게 즐기는 혼행 여행자예요. 화려한 명소보다 소박한 로컬 풍경을 사랑하고, 천천히 걸으며 눈에 담는 여행에서 힐링을 얻어요.', NULL, NOW(), NOW()),
('LVSRG', '골목 산책 메이트', '함께하는 사람들과 동네 골목을 여유롭게 거니는 여행자예요. 부담 없는 소비로 로컬의 분위기를 감상하며, 느긋한 산책 같은 여행 속에 도란도란 추억을 쌓아요.', NULL, NOW(), NOW()),
('LVSAI', '골목골목 탐색가', '가성비 루트로 로컬 구석구석을 부지런히 탐색하는 혼행 여행자예요. 적은 비용으로 숨은 스팟을 찾아내는 재미에 빠져 있고, 꽉 찬 하루 동선으로 동네를 샅샅이 눈에 담아요.', NULL, NOW(), NOW()),
('LVSAG', '동네 한바퀴 리더', '일행과 함께 알뜰하게 로컬 곳곳을 도는 부지런한 여행자예요. 합리적인 소비로 골목의 볼거리를 최대한 챙기며, 함께 걷고 구경하는 소소한 재미를 이끌어요.', NULL, NOW(), NOW()),
('LVERI', '로컬 라이프 체험러', '동네의 일상을 직접 살아보듯 체험하는 알뜰한 혼행 여행자예요. 가성비 있는 로컬 체험을 골라 느긋하게 즐기고, 여행지에서 현지인처럼 지내는 것을 좋아해요.', NULL, NOW(), NOW()),
('LVERG', '동네 체험 메이트', '함께하는 사람들과 부담 없이 로컬의 삶을 체험하는 여행자예요. 알뜰한 소비로 시장, 공방, 동네 클래스를 함께 즐기며, 여유로운 페이스로 정겨운 추억을 만들어요.', NULL, NOW(), NOW()),
('LVEAI', '찐로컬 탐험가', '로컬의 구석구석을 발로 뛰며 직접 체험하는 실속파 혼행 여행자예요. 적은 비용으로도 하루를 체험으로 가득 채우고, 관광객이 모르는 동네의 진짜 모습을 몸으로 겪어요.', NULL, NOW(), NOW()),
('LVEAG', '로컬 탐험 원정대장', '일행을 이끌고 로컬의 체험거리를 알뜰하게 정복하는 여행자예요. 가성비 좋은 이색 체험을 찾아내는 데 능하고, 부지런한 일정으로 모두와 동네의 매력을 나눠요.', NULL, NOW(), NOW());
